    abundant_supply = supply >= 22
    tight_supply = supply <= 17

    if severe_need:
        bid = max(62.0, highest_urgent_prev + 2.5)
        if rich_urgent >= 2:
            bid += 6.0
        if tight_supply:
            bid += 6.0
        return min(budget, bid)

    if moderate_need:
        if highest_urgent_prev >= 100:
            bid = 24.0 if abundant_supply else 46.0
        else:
